INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(104512, 'ruRU', '', 'Так это ты та, кто украл МОЙ корабль и убил МОЮ команду.', 24330),
(104513, 'ruRU', '', 'Отпусти великана. У меня есть дела внутри храма.', 24330),
(104544, 'ruRU', '', 'Да, мы жаждем попировать прислужниками падшего титана. Но сперва... Закаджз.', 24330),
(104546, 'ruRU', '', 'Культисты могут попытаться снова пробудить его, или он может очнуться сам. Нам нужно поглотить его сущность, чтобы убедиться, что он исчез навсегда. Ты знаешь, что это нужно сделать.', 24330),
(104558, 'ruRU', '', 'Жуткие Клинки погубили целые флоты. Неприступные крепости по их воле захлёбывались реками крови. Одно лишь упоминание их имени вселяет страх в сердца моряков.', 24330),
(104559, 'ruRU', '', 'Им нет равных... Мне нет равных! Повернись и уйди сейчас, и, может, доживёшь, чтобы рассказать эту историю.', 24330),
(104564, 'ruRU', '', 'На мою деревню Яндвик нападают наги. Я пришёл просить твоей помощи.', 24330),
(104566, 'ruRU', '', 'Нам мешают два препятствия, $n.$B$BМы гордые воины и легко можем защитить свою деревню, но наш клан отрёкся от моря. Мы не можем победить врага, что обитает там, куда мы не можем войти.$B$BВ довершение всего, наш ярл пропал без вести. Члены нашего клана борются за власть в его отсутствие.', 24330),
(104567, 'ruRU', '', 'Защита слабеет!', 24330),
(104568, 'ruRU', '', 'Госпожа Хейткойл уязвима! Она не должна пасть!', 24330),
(104569, 'ruRU', '', 'Сородичи Яндвика! Калдер и Эйнар пали в бою. Они не были достойны вести Яндвик.', 24330),
(104570, 'ruRU', '', 'Как последнему оставшемуся наследнику, мне выпадает вести наш народ против вторгшихся наг Сашь''тар!', 24330),
(104571, 'ruRU', '', 'Этот чужеземец под моей эгидой. Те, кто проявит агрессию против $gнего:неё;, ответят передо мной.', 24330),
(104572, 'ruRU', '', 'No longer used.', 24330),
(104573, 'ruRU', '', 'No longer used.', 24330),
(104576, 'ruRU', '', 'Это будет мне в удовольствие.', 24330),
(104577, 'ruRU', '', 'Я уже видела свою судьбу. Тебя в ней нет!', 24330),
(104578, 'ruRU', '', 'Я бич морей, страх в сердцах моряков! Ты НИЧТО!', 24330),
(104579, 'ruRU', '', 'ДОВОЛЬНО! Я проткну тебя насквозь!', 24330),
(104580, 'ruRU', '', 'Похоже, у нас завелись паразиты...', 24330),
(104584, 'ruRU', '', 'Невозможно...', 24330),
(104597, 'ruRU', '', 'Приветствую! Тебя ведь не выследили?', 24330),
(104633, 'ruRU', '', 'Ты был и покорной пешкой, и занозой в моём боку, $n', 24330),
(104634, 'ruRU', '', 'Пожалуй, мне стоит поблагодарить тебя за то, что расправился с Калдером и Эйнаром за меня. Мне нужно было, чтобы все потенциальные вожди Яндвика были мертвы, но я не мог допустить, чтобы деревня заподозрила, что это я стал причиной их гибели.', 24330),
(104635, 'ruRU', '', 'Без вождя, который сплотил бы их, Яндвик падёт под совместной мощью морских великанов и моих наг в приливной волне смерти и разрушения. У моей королевы появится отличный плацдарм в Сурамаре.', 24330),
(104636, 'ruRU', '', 'Мой план работал, надоедливая слизь. Мои наги должны были убить тебя и шайку щенков Брандольфа. Но нет! У тебя хватило наглости выжить!', 24330),
(104638, 'ruRU', '', 'Я так рада, что ты последовал за мной сюда, $n. Я боялась, что ты мог наткнуться на мой план.', 24330),
(104646, 'ruRU', '', 'Этот защитник показывает талант!', 24330),
(104658, 'ruRU', '', 'Тишина. Времени мало.', 24330),
(104660, 'ruRU', '', 'Встретимся за пределами Яндвика. Не входи в деревню, пока мы снова не поговорим.', 24330),
(104672, 'ruRU', '', 'Предупреждаю тебя, мои сородичи не любят чужаков. Было бы мудро избегать ненужных конфликтов.', 24330),
(104685, 'ruRU', '', 'Нам обязательно делать это здесь?', 24330),
(104686, 'ruRU', '', 'Из портала появляется элитный отряд Легиона!', 24330),
(104692, 'ruRU', '', 'Полагаю, с одной я могу расстаться. Но передай Диди, что я выставляю ей за это счёт. Мы тут не благотворительностью занимаемся.', 24330),
(104735, 'ruRU', '', 'Я сражу их в его честь!', 24330),
(104737, 'ruRU', '', 'Мудрый выбор.', 24330),
(104756, 'ruRU', '', 'Приятно видеть новое лицо за столом! А то я уже устал от уродливой физиономии Тетис... Без обид, Тетис.', 24330),
(104779, 'ruRU', '', 'Прошу прощения, но это мой самоцвет. Не мог бы ты его не трогать?', 24330),
(104781, 'ruRU', '', 'Ох, ну тогда я сейчас спущусь. Иду!', 24330),
(104783, 'ruRU', '', 'Привет, меня кто-то искал?', 24330);
